import React, { useState, useEffect } from 'react';
import axios from 'axios';
import Loader from './Loader';
import DevNoticeModal from './DevNoticeModal';
import '../styles/HomePage.css';
import '../styles/DevNoticeModal.css';

const HomePage = ({ onNavigate }) => {
  // State for popular stocks prices
  const [stockPrices, setStockPrices] = useState({});
  const [loading, setLoading] = useState(true);

  // State untuk modal - SET TRUE untuk memastikan muncul
  const [showDevNotice, setShowDevNotice] = useState(() => {
  // Cek localStorage saat komponen diinisialisasi
  const acknowledged = localStorage.getItem('devNoticeAcknowledged');
  console.log("Initial devNoticeAcknowledged value:", acknowledged);
  
  // Jika 'permanent', maka sembunyikan modal
  if (acknowledged === 'permanent') {
    console.log("Modal permanently hidden");
    return false;
  }

  // Jika nilai acknowledged adalah timestamp
  if (acknowledged && acknowledged !== 'permanent') {
    try {
      const acknowledgedTime = parseInt(acknowledged, 10);
      const now = Date.now();
      
      // Ubah dari 24 jam menjadi 2 jam (7200000 ms)
      // Dalam development mode, gunakan 30 detik untuk testing
      const timerDuration = process.env.NODE_ENV === 'development' ? 30 * 1000 : 2 * 60 * 60 * 1000;
      
      // Jika belum lebih dari durasi timer, jangan tampilkan modal
      if (now - acknowledgedTime < timerDuration) {
        console.log(`Not showing modal - less than ${process.env.NODE_ENV === 'development' ? '30s' : '2h'} since last closed`);
        console.log(`Time elapsed: ${((now - acknowledgedTime)/1000).toFixed(2)} seconds`);
        console.log(`Modal will show again at: ${new Date(acknowledgedTime + timerDuration).toLocaleTimeString()}`);
        return false;
      } else {
        console.log(`More than ${process.env.NODE_ENV === 'development' ? '30s' : '2h'} since last closed, showing modal`);
        // Reset timestamp di localStorage, karena timer sudah habis
        localStorage.removeItem('devNoticeAcknowledged');
        return true;
      }
    } catch (e) {
      console.error('Error parsing timestamp:', e);
      localStorage.removeItem('devNoticeAcknowledged'); // Reset jika terjadi error
      return true;
    }
  }
    
  // Default: tampilkan modal jika tidak ada data di localStorage
  console.log("No acknowledgment found, showing modal");
  return true;
});

// Fungsi untuk menutup modal yang diperbarui
const handleCloseDevNotice = (dontShowAgain) => {
  console.log("Modal ditutup, jangan tampilkan lagi:", dontShowAgain);
  
  // Selalu sembunyikan modal
  setShowDevNotice(false);
  
  if (dontShowAgain) {
    // Jika dicentang "jangan tampilkan lagi", set permanent
    localStorage.setItem('devNoticeAcknowledged', 'permanent');
    console.log("Setting permanent hide for DevNoticeModal");
  } else {
    // Jika hanya ditutup, simpan timestamp saat ini
    const now = Date.now();
    localStorage.setItem('devNoticeAcknowledged', now.toString());
    
    // Tambahkan waktu yang jelas kapan akan muncul kembali
    const timerDuration = process.env.NODE_ENV === 'development' ? 30 * 1000 : 2 * 60 * 60 * 1000;
    const nextShowTime = new Date(now + timerDuration);
    console.log(`Modal ditutup, jangan tampilkan lagi: ${dontShowAgain}`);
    console.log(`Modal will show again after refresh at: ${nextShowTime.toLocaleTimeString()}`);
  }
};

useEffect(() => {
  // Hanya berlaku jika modal sedang tidak ditampilkan
  if (!showDevNotice) {
    // Set interval untuk mengecek setiap 5 detik
    const checkTimerInterval = setInterval(() => {
      // Cek localStorage untuk status saat ini
      const acknowledged = localStorage.getItem('devNoticeAcknowledged');
      
      // Skip jika permanent atau tidak ada
      if (acknowledged === 'permanent' || !acknowledged) {
        return;
      }
      
      try {
        const acknowledgedTime = parseInt(acknowledged, 10);
        const now = Date.now();
        const timerDuration = process.env.NODE_ENV === 'development' ? 30 * 1000 : 2 * 60 * 60 * 1000;
        
        // Jika sudah lebih dari durasi timer, tampilkan modal
        if (now - acknowledgedTime >= timerDuration) {
          console.log(`Timer expired (${((now - acknowledgedTime)/1000).toFixed(2)}s elapsed), showing modal`);
          localStorage.removeItem('devNoticeAcknowledged'); // Reset localStorage
          setShowDevNotice(true); // Tampilkan modal
        } else {
          // Log progress (hanya di mode development)
          if (process.env.NODE_ENV === 'development') {
            console.log(`Time elapsed: ${((now - acknowledgedTime)/1000).toFixed(2)} seconds`);
            console.log(`Modal will show again at: ${new Date(acknowledgedTime + timerDuration).toLocaleTimeString()}`);
          }
        }
      } catch (e) {
        console.error('Error checking timer:', e);
        localStorage.removeItem('devNoticeAcknowledged'); // Reset jika terjadi error
      }
    }, 5000); // Cek setiap 5 detik
    
    return () => clearInterval(checkTimerInterval);
  }
}, [showDevNotice]);


useEffect(() => {
  // Hanya berlaku jika modal sedang tidak ditampilkan
  if (!showDevNotice) {
    // Cek localStorage
    const acknowledged = localStorage.getItem('devNoticeAcknowledged');
    
    // Skip jika permanent atau tidak ada
    if (acknowledged !== 'permanent' && acknowledged) {
      const checkTimerInterval = setInterval(() => {
        try {
          const acknowledgedTime = parseInt(acknowledged, 10);
          const now = Date.now();
          const timerDuration = process.env.NODE_ENV === 'development' ? 30 * 1000 : 24 * 60 * 60 * 1000;
          
          // Jika sudah lebih dari durasi timer, tampilkan modal
          if (now - acknowledgedTime >= timerDuration) {
            console.log("Timer expired, showing modal");
            setShowDevNotice(true);
            clearInterval(checkTimerInterval);
          }
        } catch (e) {
          console.error('Error checking timer:', e);
          clearInterval(checkTimerInterval);
        }
      }, 5000); // Cek setiap 5 detik
      
      return () => clearInterval(checkTimerInterval);
    }
  }
}, [showDevNotice]);


  // Popular stocks from main App
  const popularStocks = [
    { symbol: 'BBCA.JK', name: 'Bank Central Asia' },
    { symbol: 'BBRI.JK', name: 'Bank Rakyat Indonesia' },
    { symbol: 'TLKM.JK', name: 'Telkom Indonesia' },
    { symbol: 'BBNI.JK', name: 'Bank Negara Indonesia' }, // Mengganti ^JKSE dengan BBNI.JK
    { symbol: 'BMRI.JK', name: 'Bank Mandiri' },
    { symbol: 'ASII.JK', name: 'Astra International' },
    { symbol: 'UNVR.JK', name: 'Unilever Indonesia' },
    { symbol: 'ICBP.JK', name: 'Indofood CBP' }
  ];

  // Fetch latest prices for popular stocks
  useEffect(() => {
    const fetchLatestPrices = async () => {
      setLoading(true);

      try {
        const promises = popularStocks.map(async (stock) => {
          try {
            const res = await axios.get("http://localhost:5000/stock", {
              params: {
                symbol: stock.symbol,
                interval: '1d',
                period: '5d'
              }
            });

            if (res.data && res.data.data && Array.isArray(res.data.data) && res.data.data.length > 1) {
              const latestData = res.data.data.sort((a, b) => {
                const dateA = new Date(a.Date || a.Datetime);
                const dateB = new Date(b.Date || b.Datetime);
                return dateB - dateA; // Descending order
              });

              const latest = latestData[0];
              const previous = latestData[1];

              return {
                symbol: stock.symbol,
                price: latest.Close,
                change: latest.Close - previous.Close,
                changePercent: ((latest.Close - previous.Close) / previous.Close) * 100
              };
            }
            return { symbol: stock.symbol, price: null, change: null, changePercent: null };
          } catch (error) {
            console.error(`Error fetching data for ${stock.symbol}:`, error);
            return { symbol: stock.symbol, price: null, change: null, changePercent: null };
          }
        });

        const results = await Promise.all(promises);

        const newPrices = {};
        results.forEach(result => {
          if (result.price !== null) {
            newPrices[result.symbol] = {
              price: result.price,
              change: result.change,
              changePercent: result.changePercent
            };
          }
        });

        setStockPrices(newPrices);
      } catch (error) {
        console.error("Failed to fetch stock prices:", error);
      } finally {
        setLoading(false);
      }
    };

    fetchLatestPrices();
  }, []);

  // Helper function to format price
  const formatPrice = (price, symbol) => {
    if (price === null || price === undefined) return '-';
    const currencySymbol = symbol.endsWith('.JK') ? 'Rp' : '$'; // Ubah kondisi karena ^JKSE sudah tidak ada
    return `${currencySymbol} ${price.toLocaleString('id-ID')}`;
  };

  // Render cards for popular stocks
  const renderStockCard = (stock) => {
    const priceData = stockPrices[stock.symbol];
    const isLoading = loading;
    
    const isPositive = priceData && priceData.change > 0;
    const isNegative = priceData && priceData.change < 0;
    const changeColor = isPositive ? '#4CAF50' : isNegative ? '#E53935' : '#888';
    const changeIcon = isPositive ? '▲' : isNegative ? '▼' : '•';
    
    return (
      <div 
        className="stock-card" 
        key={stock.symbol}
        onClick={() => onNavigate('stocks', { symbol: stock.symbol })}
      >
        <div className="stock-card-gradient"></div>
        <div className="stock-card-content">
          <h2 className="stock-symbol">{stock.symbol}</h2>
          <p className="stock-name">{stock.name}</p>
          
          {isLoading ? (
            <div className="stock-price-skeleton">
              <div className="price-loading"></div>
              <div className="change-loading"></div>
            </div>
          ) : priceData ? (
            <div className="stock-price-container">
              <div className="stock-price">
                {formatPrice(priceData.price, stock.symbol)}
              </div>
              <div className="stock-change" style={{ color: changeColor }}>
                <span className="change-icon">{changeIcon}</span>
                <span>
                  {isPositive ? '+' : ''}{priceData.change.toFixed(2)} 
                  ({isPositive ? '+' : ''}{priceData.changePercent.toFixed(2)}%)
                </span>
              </div>
            </div>
          ) : (
            <div className="stock-price-unavailable">
              Data tidak tersedia
            </div>
          )}
        </div>
      </div>
    );
  };

  return (
    <div className="home-container">
      <div className={`content-container ${showDevNotice ? 'blurred-content' : ''}`}>
        <section className="hero-section">
          <div className="hero-content">
            <h1>Analisis Pasar Saham</h1>
            <p>Pantau pergerakan harga saham secara real-time dan analisis tren pasar dengan mudah</p>
            <button className="cta-button" onClick={() => onNavigate('stocks')}>
              Mulai Analisis
            </button>
          </div>
        </section>

        <section className="popular-stocks-section">
          <div className="section-header">
            <h2 className="section-title">Popular Stocks</h2>
          </div>
          
          {loading && <div className="center-loader"><Loader /></div>}
          
          <div className="stocks-grid">
            {popularStocks.slice(0, 8).map(renderStockCard)}
          </div>
        </section>

      <section className="features-section">
        <div className="section-header">
          <h2 className="section-title">Fitur Utama</h2>
        </div>
        
        <div className="features-grid">
          <div className="feature-card">
            <div className="feature-icon chart-icon">
              <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none">
                <defs>
                  <linearGradient id="chartGradient" x1="0%" y1="0%" x2="100%" y2="100%">
                    <stop offset="0%" stopColor="#00BCD4" />
                    <stop offset="100%" stopColor="#4DB6AC" />
                  </linearGradient>
                </defs>
                <path d="M3 3V21H21" stroke="url(#chartGradient)" strokeWidth="2" strokeLinecap="round" />
                <path d="M7 14L11 10L15 14L20 9" stroke="url(#chartGradient)" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
                <circle cx="7" cy="14" r="2" fill="#E0F7FA" stroke="url(#chartGradient)" strokeWidth="1.5" />
                <circle cx="11" cy="10" r="2" fill="#E0F7FA" stroke="url(#chartGradient)" strokeWidth="1.5" />
                <circle cx="15" cy="14" r="2" fill="#E0F7FA" stroke="url(#chartGradient)" strokeWidth="1.5" />
                <circle cx="20" cy="9" r="2" fill="#E0F7FA" stroke="url(#chartGradient)" strokeWidth="1.5" />
              </svg>
            </div>
            <h3>Grafik Interaktif</h3>
            <p>Visualisasi data saham dengan grafik interaktif beserta indikator teknikal</p>
          </div>
          
          <div className="feature-card">
            <div className="feature-icon analysis-icon">
              <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none">
                <defs>
                  <linearGradient id="analysisGradient" x1="0%" y1="0%" x2="100%" y2="100%">
                    <stop offset="0%" stopColor="#5C6BC0" />
                    <stop offset="100%" stopColor="#3F51B5" />
                  </linearGradient>
                </defs>
                <circle cx="11" cy="11" r="7" stroke="url(#analysisGradient)" strokeWidth="2" fill="#E8EAF6" />
                <path d="M11 8V11H14" stroke="url(#analysisGradient)" strokeWidth="2" strokeLinecap="round" />
                <path d="M21 21L16.65 16.65" stroke="url(#analysisGradient)" strokeWidth="2" strokeLinecap="round" />
                <circle cx="11" cy="11" r="3" fill="#C5CAE9" opacity="0.6" />
              </svg>
            </div>
            <h3>Analisis Mendalam</h3>
            <p>Dapatkan analisis mendalam tentang performa saham dan prediksi tren</p>
          </div>
          
          <div className="feature-card">
            <div className="feature-icon news-icon">
              <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none">
                <defs>
                  <linearGradient id="newsGradient" x1="0%" y1="0%" x2="100%" y2="100%">
                    <stop offset="0%" stopColor="#FF9800" />
                    <stop offset="100%" stopColor="#FB8C00" />
                  </linearGradient>
                </defs>
                <rect x="3" y="4" width="18" height="16" rx="2" stroke="url(#newsGradient)" strokeWidth="2" fill="#FFF3E0" />
                <path d="M7 9H17" stroke="url(#newsGradient)" strokeWidth="2" strokeLinecap="round" />
                <path d="M7 13H17" stroke="url(#newsGradient)" strokeWidth="2" strokeLinecap="round" />
                <path d="M7 17H13" stroke="url(#newsGradient)" strokeWidth="2" strokeLinecap="round" />
              </svg>
            </div>
            <h3>Berita Terkini</h3>
            <p>Akses berita terbaru yang mempengaruhi pasar saham dan ekonomi</p>
          </div>
          
          <div className="feature-card">
            <div className="feature-icon data-icon">
              <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none">
                <defs>
                  <linearGradient id="dataGradient" x1="0%" y1="0%" x2="100%" y2="100%">
                    <stop offset="0%" stopColor="#66BB6A" />
                    <stop offset="100%" stopColor="#43A047" />
                  </linearGradient>
                </defs>
                <rect x="3" y="3" width="5" height="18" rx="1" stroke="url(#dataGradient)" strokeWidth="2" fill="#E8F5E9" />
                <rect x="10" y="8" width="5" height="13" rx="1" stroke="url(#dataGradient)" strokeWidth="2" fill="#E8F5E9" />
                <rect x="17" y="5" width="5" height="16" rx="1" stroke="url(#dataGradient)" strokeWidth="2" fill="#E8F5E9" />
              </svg>
            </div>
            <h3>Data Historis</h3>
            <p>Telusuri data historis saham untuk analisis jangka panjang</p>
          </div>
        </div>
      </section>
      </div>
      
      {/* Tambahkan DevNoticeModal dengan prop isOpen={true} untuk testing */}
      <DevNoticeModal 
        isOpen={showDevNotice}
        onClose={handleCloseDevNotice}
      />
    </div>
  );
};

export default HomePage;
